// Osnovni kostruktor igre in ključne funkcije
const canvas = document.getElementById('gameCanvas');
const ctx = canvas.getContext('2d');

// Nastavitve velikosti platna glede na okno
function resizeCanvas() {
    canvas.width = window.innerWidth * 0.8;
    canvas.height = window.innerHeight * 0.8;
}

resizeCanvas();
window.addEventListener('resize', resizeCanvas);

// Status igre
let gameState = 'start'; // start, playing, gameover

// Igralec
const player = {
    x: 50,
    y: 0,
    width: 30,
    height: 30,
    color: '#0f0',
    speed: 5,
    dy: 0,
    gravity: 0.5,
    jumpStrength: -10,
    onGround: false,
};

// Ključi
const keys = {};

// Event listnerji za tipkovnico
window.addEventListener('keydown', function(e) {
    keys[e.code] = true;
    if (gameState === 'start' && e.code === 'Space') {
        startGame();
    } else if (gameState === 'gameover' && e.code === 'Space') {
        startGame();
    }
});

window.addEventListener('keyup', function(e) {
    keys[e.code] = false;
});

// Preprosta pregrada (tla)
const groundY = () => canvas.height - 50;

// Ovire
let obstacles = [];
let obstacleFrequency = 1500; // ms
let lastObstacleTime = 0;

// Točkovanje
let score = 0;

// Zvočni signali (preprosti fx zvočni signali preko Web Audio API)
const audioCtx = new (window.AudioContext || window.webkitAudioContext)();

function playBeep(frequency, duration=100) {
    const oscillator = audioCtx.createOscillator();
    const gainNode = audioCtx.createGain();
    oscillator.connect(gainNode);
    gainNode.connect(audioCtx.destination);
    oscillator.frequency.value = frequency;
    oscillator.type = 'square';
    oscillator.start();
    gainNode.gain.setValueAtTime(0.1, audioCtx.currentTime);
    oscillator.stop(audioCtx.currentTime + duration / 1000);
}

// Začetek igre
function startGame() {
    gameState = 'playing';
    player.x = 50;
    player.y = groundY() - player.height;
    player.dy = 0;
    obstacles = [];
    score = 0;
    lastObstacleTime = performance.now();
    requestAnimationFrame(gameLoop);
}

// Generiranje ovir
function generateObstacle() {
    const height = 20 + Math.random() * 50;
    const width = 20 + Math.random() * 30;
    const x = canvas.width;
    const y = groundY() - height;
    obstacles.push({ x, y, width, height, color: '#f00' });
}

// Preveri trk igralca z oviro
function checkCollision(rect1, rect2) {
    return rect1.x < rect2.x + rect2.width &&
           rect1.x + rect1.width > rect2.x &&
           rect1.y < rect2.y + rect2.height &&
           rect1.y + rect1.height > rect2.y;
}

// Posodobi stanje igre
function update(deltaTime) {
    if (gameState !== 'playing') return;

    // Premikanje igralca (skok)
    if (keys['Space'] || keys['ArrowUp']) {
        if (player.onGround) {
            player.dy = player.jumpStrength;
            player.onGround = false;
            playBeep(440, 100); // zvočni učinek
        }
    }

    // Fizika igralca
    player.dy += player.gravity;
    player.y += player.dy;

    // Preveri tla
    if (player.y + player.height >= groundY()) {
        player.y = groundY() - player.height;
        player.dy = 0;
        player.onGround = true;
    }

    // Premakni ovire
    const now = performance.now();
    if (now - lastObstacleTime > obstacleFrequency) {
        generateObstacle();
        lastObstacleTime = now;
        // postopno povečuje težavnost 
        if (obstacleFrequency > 500) {
            obstacleFrequency -= 20;
        }
    }

    obstacles.forEach(obstacle => {
        obstacle.x -= 5;
    });

    // Odstrani ovire, ki so izven platna
    obstacles = obstacles.filter(obstacle => obstacle.x + obstacle.width > 0);

    // Preveri trke
    for (const obs of obstacles) {
        if (checkCollision(player, obs)) {
            gameState = 'gameover';
            playBeep(220, 300);
            break;
        }
    }

    // Točkovanje
    score += deltaTime * 0.01;
}

// Nariši igro
function draw() {
    // Ozadje
    ctx.fillStyle = '#000';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    if (gameState === 'start') {
        ctx.fillStyle = '#eee';
        ctx.font = '28px Arial';
        ctx.textAlign = 'center';
        ctx.fillText('Dobrodošli v igri!', canvas.width / 2, canvas.height / 3);
        ctx.font = '20px Arial';
        ctx.fillText('Pritisnite SPACE za začetek', canvas.width / 2, canvas.height / 3 + 40);
        ctx.fillText('Skok: SPACE ali puščica gor', canvas.width / 2, canvas.height / 3 + 80);
        ctx.fillText('Cilj: premagaj ovire čim dlje!', canvas.width / 2, canvas.height / 3 + 120);
        return;
    }

    if (gameState === 'playing') {
        // Nariši igralca
        ctx.fillStyle = player.color;
        ctx.fillRect(player.x, player.y, player.width, player.height);

        // Nariši ovire
        obstacles.forEach(obs => {
            ctx.fillStyle = obs.color;
            ctx.fillRect(obs.x, obs.y, obs.width, obs.height);
        });

        // Nariši tla
        ctx.strokeStyle = '#555';
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.moveTo(0, groundY());
        ctx.lineTo(canvas.width, groundY());
        ctx.stroke();

        // Točke
        ctx.fillStyle = '#eee';
        ctx.font = '20px Arial';
        ctx.textAlign = 'left';
        ctx.fillText('Točke: ' + Math.floor(score), 10, 30);
        return;
    }

    if (gameState === 'gameover') {
        ctx.fillStyle = '#eee';
        ctx.font = '28px Arial';
        ctx.textAlign = 'center';
        ctx.fillText('Konec igre!', canvas.width / 2, canvas.height / 3);
        ctx.font = '20px Arial';
        ctx.fillText('Tvoje točke: ' + Math.floor(score), canvas.width / 2, canvas.height / 3 + 40);
        ctx.fillText('Pritisni SPACE za ponovni začetek', canvas.width / 2, canvas.height / 3 + 80);
        return;
    }
}

// Glavna zanka igre
let lastTime = performance.now();
function gameLoop(time) {
    const deltaTime = time - lastTime;
    lastTime = time;

    update(deltaTime);
    draw();

    if (gameState === 'playing') {
        requestAnimationFrame(gameLoop);
    }
}

draw();
